# Comparison with results computed by the R package biomonitoR 0.9.5
# (generated by tools/make_reference.R and stored in test/reference).

using biomonitor: read_raw, column, community_from_raw, reference_from_raw

const REF = joinpath(@__DIR__, "reference")
const TD = joinpath(@__DIR__, "data")

refnum(s) = s == "NaN" || s == "NA" || isempty(s) ? NaN : parse(Float64, s)
same(a, b; atol = 1e-8, rtol = 1e-8) = (isnan(a) && isnan(b)) || isapprox(a, b; atol, rtol)

# R data.frames prefix syntactically invalid names (e.g. numeric sample codes) with "X"
rname(s) = occursin(r"^X\d", s) ? s[2:end] : s

function refvec(name)
    t = read_raw(joinpath(REF, name * ".tsv"))
    return Dict(rname(String(k)) => refnum(v) for (k, v) in zip(column(t, "name"), column(t, "value")))
end

# `na_as`: value expected where R returns NA because of a deliberate difference
function check_vec(name, v; na_as = nothing, kw...)
    r = refvec(name)
    @test sort(collect(keys(r))) == sort(rname.(labels(v)))
    for (l0, x) in pairs(v)
        l = rname(l0)
        expected = na_as !== nothing && isnan(r[l]) ? na_as : r[l]
        ok = same(x, expected; kw...)
        ok || println("MISMATCH ", name, " ", l, " julia=", x, " R=", r[l])
        @test ok
    end
end

# table written with row names; `rowkey` picks the column used as row id
function check_mat(name, m::LabeledMatrix; rowcol = "row", kw...)
    t = read_raw(joinpath(REF, name * ".tsv"))
    rows = rname.(column(t, rowcol))
    @test sort(rows) == sort(rname.(rownames(m)))
    for c in colnames(m)
        rc = c in t.names ? c : replace(c, " " => ".")
        @test rc in t.names
        rc in t.names || continue
        vals = column(t, rc)
        for (i, r) in enumerate(rows)
            x = m.values[findfirst(==(r), rname.(rownames(m))), findfirst(==(c), colnames(m))]
            ok = same(x, refnum(vals[i]); kw...)
            ok || println("MISMATCH ", name, " ", r, " ", c, " julia=", x, " R=", vals[i])
            @test ok
        end
    end
end

function check_community(name, x::CommunityTable; taxcol = "Taxa")
    t = read_raw(joinpath(REF, name * ".tsv"))
    @test column(t, taxcol) == x.taxa || sort(column(t, taxcol)) == sort(x.taxa)
    for (j, s) in enumerate(x.samples)
        vals = refnum.(column(t, s))
        for (i, tx) in enumerate(column(t, taxcol))
            @test same(x[tx][s], vals[i])
        end
    end
end

testdata(name) = community_from_raw(read_raw(joinpath(TD, name * ".tsv")))
quiet(f) = Base.CoreLogging.with_logger(f, Base.CoreLogging.NullLogger())

@testset "parity with R biomonitoR" begin
    mex = quiet(() -> aggregate_taxa(as_biomonitor(macro_ex())))
    @testset "macro_ex diversity and data management" begin
        check_mat("macro_ex_allrich", allrich(mex))
        check_mat("macro_ex_allindices", allindices(mex))
        check_mat("macro_ex_allindices_family", allindices(mex; tax_lev = :Family))
        check_mat("macro_ex_allindices_base2", allindices(mex; base = 2))
        check_vec("macro_ex_general_info", general_info(mex))
        check_vec("macro_ex_abundance_genus", abundance(mex; tax_lev = :Genus))
        check_vec("macro_ex_taxa_abundance", get_taxa_abundance(mex, ["Ephemeroptera", "Baetis"]; rel = true))
        check_vec("macro_ex_taxa_richness", get_taxa_richness(mex, "Ephemeroptera", "Genus"))
        check_community("macro_ex_convert_to_biotic", convert_to_biotic(mex); taxcol = "Taxon")
        check_community("macro_ex_combine_taxa", combine_taxa(mex; ntaxa = 2, tax_lev = :Family))
        check_community("macro_ex_remove_taxa", remove_taxa(mex, ["Hydroptilidae", "Acentrella"]))
        check_mat("macro_ex_vegan_family", convert_to_vegan(mex; tax_lev = :Family))
    end

    @testset "macro_ex biotic indices" begin
        quiet() do
            for m in ("ita", "spa", "a", "uk")
                check_vec("macro_ex_bmwp_$(m)", bmwp(mex; method = m))
                check_vec("macro_ex_aspt_$(m)", aspt(mex; method = m))
            end
            check_vec("macro_ex_bmwp_ita_agg", bmwp(mex; method = "ita", agg = true))
            check_vec("macro_ex_aspt_uk_agg", aspt(mex; method = "uk", agg = true))
            check_vec("macro_ex_whpt_aspt", whpt(mex))
            check_vec("macro_ex_whpt_po_bmwp", whpt(mex; type = "po", metric = "bmwp"))
            check_vec("macro_ex_whpt_ntaxa_agg", whpt(mex; metric = "ntaxa", agg = true))
            check_vec("macro_ex_life", life(mex))
            check_vec("macro_ex_life_2017", life(mex; method = "life_2017", agg = true))
            check_vec("macro_ex_psi", psi(mex))
            check_vec("macro_ex_epsi", epsi(mex))
            check_vec("macro_ex_epsi_agg", epsi(mex; agg = true))
            check_vec("macro_ex_dehli", dehli(mex))
            check_vec("macro_ex_igold", igold(mex))
            check_vec("macro_ex_ept", ept(mex))
            check_vec("macro_ex_ept_family", ept(mex; tax_lev = :Family))
            check_vec("macro_ex_eptd", eptd(mex))
        end
    end

    @testset "macro_ex traits" begin
        quiet() do
            ts = assign_traits(mex)
            t = read_raw(joinpath(REF, "macro_ex_assign_traits.tsv"))
            rset = Set(zip(column(t, "Taxa"), column(t, "Taxa_db"), column(t, "Traits_taxlev"), column(t, "Traits_real"),
                           parse.(Int, column(t, "Taxonomic_distance"))))
            jset = Set(zip(ts.taxa, string.(ts.taxa_level), ts.trait_taxa, string.(ts.trait_level), ts.distance))
            @test rset == jset
            @test length(ts) == length(column(t, "Taxa"))
            mt = manage_traits(ts; method = "nearest+-")
            t2 = read_raw(joinpath(REF, "macro_ex_manage_traits.tsv"))
            @test Set(zip(column(t2, "Taxa"), column(t2, "Traits_taxlev"))) == Set(zip(mt.taxa, mt.trait_taxa))
            av = average_traits(ts)
            check_mat("macro_ex_average_traits", LabeledMatrix(av.taxa, av.traits, av.values))
            check_mat("macro_ex_cwm", cwm(mex; trait_db = av); rowcol = "Sample")
            check_mat("macro_ex_csi", csi(mex); rowcol = "Sample")
            check_mat("macro_ex_tsi", tsi(mex))
            check_vec("macro_ex_flow_t", flow_t(mex))
            bi = bio_index(mex; index = ["trophic_t", "saprobity_t", "temperature_t"])
            m = LabeledMatrix(samples(mex), ["trophic_t", "saprobity_t", "temperature_t"],
                              hcat(bi.trophic_t.values, bi.saprobity_t.values, bi.temperature_t.values))
            check_mat("macro_ex_bio_index", m)
            tsf = assign_traits(mex; tax_lev = :Family)
            t3 = read_raw(joinpath(REF, "macro_ex_assign_traits_family.tsv"))
            @test Set(zip(column(t3, "Taxa"), column(t3, "Traits_taxlev"), parse.(Int, column(t3, "Taxonomic_distance")))) ==
                  Set(zip(tsf.taxa, tsf.trait_taxa, tsf.distance))
        end
    end

    @testset "macro_ex functional diversity" begin
        quiet() do
            av = average_traits(assign_traits(mex))
            cb = biomonitor.DEFAULT_TACHET_BLOCKS
            G = gower_fuzzy(prep_fuzzy(av, cb), cb)
            check_mat("macro_ex_gower", LabeledMatrix(G.labels, G.labels, G.d))
            @test is_euclid(G)
            check_vec("macro_ex_f_rich_2", f_rich(mex; trait_db = av, type = "F", col_blocks = cb))
            check_vec("macro_ex_f_rich_3", f_rich(mex; trait_db = av, type = "F", col_blocks = cb, nbdim = 3))
            check_vec("macro_ex_f_rich_4", f_rich(mex; trait_db = av, type = "F", col_blocks = cb, nbdim = 4))
            check_vec("macro_ex_f_disp_3", f_disp(mex; trait_db = av, type = "F", col_blocks = cb, nbdim = 3))
            check_vec("macro_ex_f_eve_3", f_eve(mex; trait_db = av, type = "F", col_blocks = cb, nbdim = 3))
            check_vec("macro_ex_f_divs", f_divs(mex; trait_db = av, type = "F", col_blocks = cb))
            check_mat("macro_ex_f_red", f_red(mex; trait_db = av, type = "F", col_blocks = cb))
            check_vec("macro_ex_qfs", qfs(G; nbdim = 10).meanSD)
            sl = select_pcoa_axes(G; method = "legendre")
            t = read_raw(joinpath(REF, "macro_ex_select_legendre.tsv"))
            @test sl[1].nbdim == parse(Int, column(t, "nbdim")[1])
            @test same(sl[1].r2, refnum(column(t, "r2")[1]))
            sm = select_pcoa_axes(G; method = "maire")
            t = read_raw(joinpath(REF, "macro_ex_select_maire.tsv"))
            @test sm[1].nbdim == parse(Int, column(t, "nbdim")[1])
            @test same(sm[1].SD, refnum(column(t, "SD")[1]))
            @test same(sm[1].r2, refnum(column(t, "r2")[1]))
        end
    end

    mip = quiet(() -> aggregate_taxa(as_biomonitor(mi_prin())))
    @testset "mi_prin" begin
        quiet() do
            check_mat("mi_prin_allindices", allindices(mip))
            check_mat("mi_prin_allrich", allrich(mip))
            check_vec("mi_prin_bmwp_ita_agg", bmwp(mip; method = "ita", agg = true))
            check_vec("mi_prin_aspt_ita", aspt(mip; method = "ita"))
            check_vec("mi_prin_aspt_spa", aspt(mip; method = "spa"))
            check_vec("mi_prin_whpt", whpt(mip; agg = true))
            check_vec("mi_prin_life", life(mip))
            # R gives NA when a sample has scored but no sensitive taxa; here 0
            check_vec("mi_prin_psi", psi(mip); na_as = 0.0)
            check_vec("mi_prin_epsi", epsi(mip))
            check_vec("mi_prin_dehli", dehli(mip))
            check_vec("mi_prin_ept", ept(mip; tax_lev = :Family))
            check_vec("mi_prin_igold", igold(mip))
            check_vec("mi_prin_eptd", eptd(mip))
            check_vec("mi_prin_dness_family", dness(mip; tax_lev = :Family, complete = true))
            check_vec("mi_prin_dness_family_st", dness(mip; tax_lev = :Family, complete = true, method = "delta.st"))
            check_vec("mi_prin_dness_family_bin", dness(mip; tax_lev = :Family, complete = true, method = "delta.bin"))
            avp = average_traits(assign_traits(mip))
            check_mat("mi_prin_cwm", cwm(mip; trait_db = avp); rowcol = "Sample")
            check_mat("mi_prin_csi", csi(mip); rowcol = "Sample")
            cb = biomonitor.DEFAULT_TACHET_BLOCKS
            G = gower_fuzzy(prep_fuzzy(avp, cb), cb)
            check_mat("mi_prin_gower", LabeledMatrix(G.labels, G.labels, G.d))
            @test !is_euclid(G)
            for (f, name) in ((cailliez, "cailliez"), (lingoes, "lingoes"), (quasieuclid, "quasi"))
                C = f(G)
                check_mat("mi_prin_$(name)", LabeledMatrix(C.labels, C.labels, C.d); atol = 1e-7)
            end
            for cr in ("cailliez", "lingoes", "sqrt", "quasi")
                check_vec("mi_prin_f_rich_3_$(cr)", f_rich(mip; trait_db = avp, type = "F", col_blocks = cb, nbdim = 3, correction = cr); atol = 1e-7)
                check_vec("mi_prin_f_divs_$(cr)", f_divs(mip; trait_db = avp, type = "F", col_blocks = cb, correction = cr); atol = 1e-7)
                check_mat("mi_prin_f_red_$(cr)", f_red(mip; trait_db = avp, type = "F", col_blocks = cb, correction = cr); atol = 1e-7)
            end
            check_vec("mi_prin_f_rich_3", f_rich(mip; trait_db = avp, type = "F", col_blocks = cb, nbdim = 3))
            check_vec("mi_prin_f_disp_3", f_disp(mip; trait_db = avp, type = "F", col_blocks = cb, nbdim = 3))
            check_vec("mi_prin_f_eve_3", f_eve(mip; trait_db = avp, type = "F", col_blocks = cb, nbdim = 3))
            check_vec("mi_prin_f_rich_auto", f_rich(mip; trait_db = avp, type = "F", col_blocks = cb, nbdim = :auto, correction = "cailliez"); atol = 1e-7)
            check_vec("mi_prin_f_rich_zero", f_rich(mip; trait_db = avp, type = "F", col_blocks = cb, nbdim = 3, zerodist_rm = true, correction = "lingoes"); atol = 1e-7)
            sl = select_pcoa_axes(G; method = "legendre")
            t = read_raw(joinpath(REF, "mi_prin_select_legendre.tsv"))
            @test [r.Transformation for r in sl] == column(t, "Transformation")
            @test [r.Euclidean for r in sl] == column(t, "Euclidean")
            @test [r.nbdim for r in sl] == parse.(Int, column(t, "nbdim"))
            @test all(same.([r.r2 for r in sl], refnum.(column(t, "r2")); atol = 1e-7))
        end
    end

    @testset "presence-absence" begin
        quiet() do
            mexb = aggregate_taxa(as_biomonitor(macro_ex(); FUN = bin))
            check_mat("macro_ex_bin_allindices", allindices(mexb))
            check_vec("macro_ex_bin_bmwp_ita", bmwp(mexb; method = "ita"))
            check_vec("macro_ex_bin_aspt_ita", aspt(mexb; method = "ita"))
            check_vec("macro_ex_bin_whpt_po", whpt(mexb; type = "po"))
            check_vec("macro_ex_bin_life", life(mexb))
            check_vec("macro_ex_bin_igold", igold(mexb))
        end
    end

    @testset "UK data with custom reference" begin
        quiet() do
            ref_def = reference_from_raw(read_raw(joinpath(TD, "ref_def.tsv")))
            tct = read_raw(joinpath(TD, "to_change.tsv"))
            tc = [a => b for (a, b) in zip(column(tct, "Taxon"), column(tct, "Correct_Taxon"))]
            uk = aggregate_taxa(as_biomonitor(testdata("taxa_uk_data"); dfref = ref_def, to_change = tc))
            check_vec("uk_life_2017", life(uk; method = "life_2017"))
            check_vec("uk_whpt_agg", whpt(uk; method = "uk", agg = true))
            check_vec("uk_whpt_bmwp_agg", whpt(uk; method = "uk", metric = "bmwp", agg = true))
            check_vec("uk_psi", psi(uk))
            check_vec("uk_bmwp_uk_agg", bmwp(uk; method = "uk", agg = true))
            check_vec("uk_epsi", epsi(uk))
            alien = ["Potamopyrgus antipodarum", "Crangonyx pseudogracilis", "Crangonyx", "Dikerogammarus",
                     "Dikerogammarus haemobaphes", "Chelicorophium curvispinum", "Corbicula fluminea", "Hypania invalida",
                     "Dreissena polymorpha", "Dugesia tigrina"]
            bio = aggregate_taxa(as_biomonitor(testdata("data_uk_bioco"); dfref = ref_def))
            check_mat("bioco", bioco(bio; alien, dfref = ref_def, digits = 3))
            spa = aggregate_taxa(as_biomonitor(testdata("aspt_bmwp_spain")))
            check_vec("spain_bmwp_exc", bmwp(spa; method = "spa", exceptions = "Ferrissia"))
            check_vec("spain_aspt_spa", aspt(spa; method = "spa"))
        end
    end

    @testset "macrophytes" begin
        quiet() do
            ib = aggregate_taxa(as_biomonitor(testdata("ibmr_taxa"); group = :mf))
            rem = ["Spirogyra dubia", "Spirogyra gracilis", "Spirogyra majuscola", "Spirogyra parva"]
            check_vec("ibmr_coef_exc", ibmr(ib; coverage_coef = true, exceptions = rem))
            check_vec("ibmr_coef", ibmr(ib; coverage_coef = true))
            og = aggregate_taxa(as_biomonitor(oglio(); group = :mf, FUN = bin))
            check_vec("oglio_dness", dness(og; method = "delta", complete = true))
            check_vec("oglio_dness_st", dness(og; method = "delta.st", complete = true))
            check_mat("oglio_allrich", allrich(og))
            ts = assign_traits(og; trait_db = traits_mf(), group = :mf)
            t = read_raw(joinpath(REF, "oglio_assign_traits.tsv"))
            @test Set(zip(column(t, "Taxa"), column(t, "Traits_taxlev"), parse.(Int, column(t, "Taxonomic_distance")))) ==
                  Set(zip(ts.taxa, ts.trait_taxa, ts.distance))
        end
    end

    @testset "ambiguous taxa and reference trees" begin
        quiet() do
            amb = aggregate_taxa(as_biomonitor(testdata("ambiguous_df"); FUN = sum))
            check_community("ambiguous_mcwp", solve_ambiguous(amb; method = "MCWP"))
            check_community("ambiguous_rpkc", solve_ambiguous(amb; method = "RPKC"))
            ref = ref_from_tree(example_tree()...)
            t = read_raw(joinpath(REF, "ref_from_tree.tsv"))
            rset = Set(collect(r) for r in zip((column(t, string(l)) for l in TAXONOMIC_LEVELS)...))
            jset = Set([ref.ranks[i, :]; ref.taxa[i]] for i in eachindex(ref.taxa))
            @test rset == jset
        end
    end

    @testset "convex hull and clustering" begin
        t = read_raw(joinpath(REF, "hull_points.tsv"))
        P = reduce(hcat, [refnum.(column(t, c)) for c in t.names[2:end]])
        v = refvec("hull_volumes")
        @test convex_hull_volume(P[:, 1:2]) ≈ v["d2"]
        @test convex_hull_volume(P[:, 1:3]) ≈ v["d3"]
        @test convex_hull_volume(P) ≈ v["d4"]
        D = [sqrt(sum(abs2, P[i, :] .- P[j, :])) for i in axes(P, 1), j in axes(P, 1)]
        for (file, meth) in (("hclust_cutree", "ward.D2"), ("hclust_cutree_average", "average"))
            tc = read_raw(joinpath(REF, file * ".tsv"))
            tr = hclust(D; method = meth)
            for (j, k) in enumerate(2:6)
                @test cutree(tr, k) == parse.(Int, tc.columns[j+1])
            end
        end
    end
end
